CREATE TABLE IF NOT EXISTS l16_store_daily (
  ss_store_sk INT, sales_date DATE, net_paid DECIMAL(17,2), tickets BIGINT, d_year INT
);
DELETE FROM l16_store_daily WHERE d_year = 2001;
INSERT INTO l16_store_daily (ss_store_sk, sales_date, net_paid, tickets, d_year)
SELECT ss.ss_store_sk, d.d_date, SUM(ss.ss_net_paid), COUNT(DISTINCT ss.ss_ticket_number), 2001
FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk
WHERE d.d_year = 2001 AND d.d_moy = 1
GROUP BY ss.ss_store_sk, d.d_date;
SELECT * FROM l16_store_daily ORDER BY d_year, sales_date, ss_store_sk
